previewCss:
.darma-loader-darma-b11-ufo-beam { --accent: var(--loader-color, #22c55e); --accent-2: var(--loader-secondary-color, #bbf7d0); width: var(--loader-size, 88px); height: var(--loader-size, 88px); position: relative; overflow: hidden; }
.darma-loader-darma-b11-ufo-beam .darma-loader-darma-b11-ufo-beam__ufo { position: absolute; top: 24%; left: 50%; width: 56%; height: 18%; margin-left: -28%; background: linear-gradient(#e2e8f0, #64748b); border-radius: 50%; animation: darma-loader-darma-b11-ufo-beam-hover calc(var(--loader-speed, 1s) * 2.2) ease-in-out infinite; z-index: 2; }
.darma-loader-darma-b11-ufo-beam .darma-loader-darma-b11-ufo-beam__ufo::before { content: ''; position: absolute; left: 50%; top: -55%; width: 44%; height: 105%; margin-left: -22%; background: radial-gradient(circle at 50% 40%, color-mix(in srgb, #fff 45%, var(--accent)), var(--accent)); border-radius: 50% 50% 0 0; }
.darma-loader-darma-b11-ufo-beam .darma-loader-darma-b11-ufo-beam__ufo::after { content: ''; position: absolute; left: 50%; top: 90%; width: 74%; height: calc(var(--loader-size, 88px) * .5); margin-left: -37%; background: linear-gradient(var(--accent-2), transparent); clip-path: polygon(30% 0, 70% 0, 100% 100%, 0 100%); animation: darma-loader-darma-b11-ufo-beam-beam calc(var(--loader-speed, 1s) * 1.4) ease-in-out infinite; }
@keyframes darma-loader-darma-b11-ufo-beam-hover { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-12%); } }
@keyframes darma-loader-darma-b11-ufo-beam-beam { 0%, 100% { opacity: .3; } 50% { opacity: .75; } }

